<template><main class="author-page"><div class="author-bg"></div><section class="shell"><header class="topbar"><button type="button" @click="router.back()">← 返回</button><strong>✿ Travel Memory</strong><button type="button" @click="router.push('/discover')">发现</button></header><section v-if="loading" class="state">✿ 正在打开旅行者主页…</section><section v-else-if="error||!profile" class="state"><strong>暂时无法打开这个主页</strong><p>{{ error||'用户不存在' }}</p></section><template v-else><section class="profile-hero"><div class="identity"><UserAvatar :user-id="profile.id" :avatar="profile.avatar" :name="profile.displayName" :size="118"/><div><p class="eyebrow">PUBLIC TRAVEL CREATOR</p><h1>{{ profile.displayName }}</h1><span>@{{ profile.username }}</span></div></div><div class="stats"><span><b>{{ profile.publicTravelCount }}</b>公开旅程</span><span><b>{{ profile.followerCount }}</b>关注者</span></div><button v-if="!isMe" type="button" class="follow" :class="{active:profile.following}" :disabled="followBusy" @click="toggleFollow">{{ profile.following?'✓ 已关注':'＋ 关注作者' }}</button></section><section class="journey-head"><div><p class="eyebrow">PUBLIC JOURNEYS</p><h2>公开旅行手账 <span>✿</span></h2></div></section><section v-if="!profile.travels.length" class="state">♡ 这个旅行者还没有公开旅程。</section><div v-else class="travel-grid"><DiscoverTravelCard v-for="(travel,index) in profile.travels" :key="travel.id" :travel="travel" :featured="index===0" @open="openJourney" @author="()=>{}" @liked="onLiked" @followed="onFollowed"/></div></template></section></main></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import UserAvatar from '@/components/UserAvatar.vue';import DiscoverTravelCard from '@/components/DiscoverTravelCard.vue';import {followAuthor} from '@/api/social';import {getPublicUserProfileApi,type PublicUserProfile} from '@/api/profile'
const route=useRoute(),router=useRouter();const profile=ref<PublicUserProfile|null>(null),loading=ref(true),error=ref(''),followBusy=ref(false);const targetUserId=computed(()=>Number(route.params.id||0));const currentUserId=(()=>{try{return Number(JSON.parse(localStorage.getItem('travel_user')||'{}').id||0)}catch{return 0}})();const isMe=computed(()=>currentUserId>0&&currentUserId===targetUserId.value);
watch(targetUserId, async (id, _, cleanup) => {
  let stale = false
  cleanup(() => { stale = true })
  loading.value = true
  error.value = ''
  profile.value = null
  try {
    const result = await getPublicUserProfileApi(id)
    if (stale) return
    if (result.code !== 200) throw new Error(result.message || '读取作者主页失败')
    profile.value = result.data
  } catch (e) {
    if (!stale) error.value = e instanceof Error ? e.message : '读取作者主页失败'
  } finally {
    if (!stale) loading.value = false
  }
}, { immediate: true })
async function toggleFollow(){if(!profile.value||isMe.value||followBusy.value)return;followBusy.value=true;try{const next=!profile.value.following;const r=await followAuthor(profile.value.id,next);if(r.code!==200)throw new Error(r.message||'关注失败');profile.value.following=Boolean(r.data);profile.value.followerCount=Math.max(0,profile.value.followerCount+(profile.value.following?1:-1));for(const t of profile.value.travels)t.following=profile.value.following}catch(e){error.value=e instanceof Error?e.message:'关注失败'}finally{followBusy.value=false}}
function onLiked(p:{id:number;liked:boolean;likeCount:number}){const t=profile.value?.travels.find(x=>x.id===p.id);if(t){t.liked=p.liked;t.likeCount=p.likeCount}}
function onFollowed(p:{authorId:number;following:boolean}){if(!profile.value)return;profile.value.following=p.following;for(const t of profile.value.travels)t.following=p.following}
function openJourney(id:number){void router.push(`/journey/${id}`)}
</script>
<style scoped>.author-page{position:relative;min-height:100vh;padding:22px;color:#77445f;background:#ffeaf2}.author-bg{position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 10% 8%,rgba(255,255,255,.95),transparent 27%),radial-gradient(circle at 88% 18%,rgba(255,213,231,.75),transparent 31%),linear-gradient(145deg,#fff2f7,#f9d8e8)}.shell{position:relative;z-index:1;width:min(1200px,100%);margin:0 auto}.topbar{min-height:58px;display:flex;align-items:center;justify-content:space-between;padding:8px 13px;border:1px solid rgba(255,255,255,.82);border-radius:20px;background:rgba(255,249,252,.68);backdrop-filter:blur(18px)}.topbar button{border:0;cursor:pointer;color:#96617a;background:none}.profile-hero{margin-top:18px;padding:34px;display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:25px;border:1px solid rgba(255,255,255,.9);border-radius:30px;background:rgba(255,248,252,.76);box-shadow:0 24px 70px rgba(196,100,141,.14);backdrop-filter:blur(20px)}.identity{display:flex;align-items:center;gap:22px}.eyebrow{margin:0 0 7px;color:#c67498;font-size:9px;font-weight:800;letter-spacing:.17em}.identity h1{margin:0;color:#75425c;font-size:clamp(28px,4vw,48px)}.identity span{color:#aa7a91;font-size:12px}.stats{display:flex;gap:8px}.stats span{min-width:96px;padding:12px;border-radius:16px;color:#a2748b;font-size:10px;text-align:center;background:rgba(255,255,255,.72)}.stats b{display:block;color:#804b66;font-size:20px}.follow{min-width:120px;padding:12px 16px;border:0;border-radius:999px;cursor:pointer;color:#75435d;font-weight:900;background:linear-gradient(120deg,#ffcbe0,#ffefbd)}.follow.active{background:#f8e5ee}.journey-head{margin:30px 0 14px}.journey-head h2{margin:0;font-size:28px}.journey-head h2 span{color:#d27a9f}.travel-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.state{min-height:260px;margin-top:18px;padding:25px;display:grid;place-content:center;gap:10px;border:1px solid rgba(255,255,255,.85);border-radius:26px;color:#996a81;text-align:center;background:rgba(255,249,252,.72);backdrop-filter:blur(18px)}@media(max-width:900px){.profile-hero{grid-template-columns:1fr}.travel-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.author-page{padding:12px}.identity{align-items:flex-start}.stats{width:100%}.stats span{flex:1}.travel-grid{grid-template-columns:1fr}}</style>
